      "content": "/**\n * opencues-core/sources/routed-word-source-group.ts\n *\n * Wraps multiple word-cue ConfigSource children and dispatches each\n * highlighted word to ONE of them based on per-source `match:` /\n * `keywords:` rules + priority. Routing is purely fast-path — no LLM\n * classifier is consulted.\n *\n * Why not \"combine all sources into one giant prompt\" (the previous\n * approach in build-sources.ts):\n *\n * - Cross-contamination: a sloppy or hijacking prompt in one source\n *   could affect ALL words. (See sync-demo class of bug.)\n * - Scaling: combined prompts grow linearly with source count and\n *   start confusing the LLM at ~5+ domains.\n *\n * Routing rules (per word):\n *\n *   - Try each source in priority-descending order.\n *   - First source whose `match:` regex hits the word OR whose\n *     `keywords:` list contains it wins.\n *   - No match → no cue. The word is not navigable. Sources without\n *     `match:`/`keywords:` are rejected by the constructor; every\n *     cue source must declare its scope.\n */\n\nimport {\n  CueSource,\n  CueContext,\n  CueSourceResult,\n  CueResult,\n} from '../types';\nimport { ConfigSource } from './config-source';\nimport type { DecisionLegs } from '../decisions/legs';\nimport { getDehydrator } from '../dehydrate';\n\nexport interface RoutedWordSourceGroupConfig {\n  /** Group identifier (default: 'word-cues'). */\n  id?: string;\n  /** A decision package with a `wordGate` leg: per child source, one request\n   *  asks which of its claimed words deserve an alternative; only those go to\n   *  the chat call, and none → no call. Absent → every claimed word goes. */\n  decisions?: DecisionLegs;\n  /** send a word to the cue's call at gate ≥ this */\n  wordGateThreshold?: number;\n  /** Child sources — one per ### alternatives section, scope: words. */\n  sources: ConfigSource[];\n  /** Debug-log sink (wire to the host's debug log). Child dispatch\n   *  FAILURES are reported here — the resolver ignores per-source\n   *  `error` fields, so this line is the only failure signal a\n   *  misbehaving provider produces. */\n  log?: (msg: string) => void;\n}\n\ninterface RouteEntry {\n  source: ConfigSource;\n  matchRe?: RegExp;\n  keywords?: string[];\n  priority: number;\n}\n\n/**\n * Determine whether the LAST word in the buffer is \"in-progress\" —\n * actively being typed by the user. Used to skip that word from\n * word-cue dispatch so the LLM doesn't burn round-trips on partial\n * words it would correctly ignore anyway.\n *\n * Returns the trailing word's index (in `context.words`) when ALL of:\n *   - The buffer is non-empty AND\n *   - The buffer doesn't end in whitespace (so the last word hasn't\n *     been \"closed\" with a space/newline) AND\n *   - The cursor is **known** AND sits at the end of the buffer (the\n *     user is actively typing there, not editing mid-text).\n *\n * Returns null otherwise — including:\n *   - Cursor in the middle of the buffer (mid-edit) — skipping the\n *     trailing word would silently regress mid-text spelling cues.\n *   - Cursor undefined (headless tests, agentic bare-injection,\n *     hosts that don't expose cursor) — we can't tell typing from\n *     pasted/edit-after, so we let everything through. The perf gate\n *     is a production optimisation, not a correctness guarantee;\n *     defaulting to \"include\" when we don't know is the structurally\n *     safer choice (June 2026 — the earlier \"assume end-of-buffer\"\n *     default silently dropped single-word inputs in every test that\n *     omits `cursor`, masking real cue regressions).\n *\n * Production hosts (CC v2.1, OC v1.14, gemini-cli, chrome, shell)\n * always pass `cursor`, so the optimisation still fires on every\n * real typing surface.\n */\nfunction findInProgressTrailingWord(context: CueContext): number | null {\n  const text = context.text;\n  if (text.length === 0) return null;\n  // Buffer ends with whitespace → last word is complete (user typed\n  // space after finishing it).\n  if (/\\s$/.test(text)) return null;\n  // Cursor must be known AND at end-of-buffer for the gate to fire.\n  // Anything else (undefined cursor, cursor mid-text) → don't skip.\n  if (context.cursor === undefined || context.cursor < text.length) {\n    return null;\n  }\n  // Trailing word is in-progress: return its index in `context.words`.\n  // `words` is space-split, so the last entry corresponds to the last\n  // non-whitespace run in the buffer.\n  if (context.words.length === 0) return null;\n  return context.words.length - 1;\n}\n\n/** send a claimed word to its cue's call at gate ≥ this */\nexport const WORD_GATE_THRESHOLD = 0.5;\n/** above this many claimed words the gate is skipped and the call runs as before */\nexport const WORD_GATE_MAX_WORDS = 60;\n\nexport class RoutedWordSourceGroup implements CueSource {\n  readonly id: string;\n  readonly priority: number;\n  /** RoutedWordSourceGroup wraps word-cue ConfigSources — always\n   *  cycleable since cues by definition surface alternatives the\n   *  user picks between. Hosts without a cycling surface skip the\n   *  whole group at registration. */\n  readonly isCycleable = true;\n\n  /** Sources with `match:` or `keywords:` — checked priority desc. */\n  private readonly entries: readonly RouteEntry[];\n\n  /**\n   * Per-child-source LRU cache of dispatch results, keyed on the EXACT\n   * sub-context text the child source receives (`0=cat 1=sat 2=the`).\n   * Hits when the LLM input is unchanged from a recent dispatch —\n   * common during typing (every space the user types reproduces the\n   * prior word set), edit-revisit loops, and after cursor moves that\n   * re-fire the debounce on identical text.\n   *\n   * Caches BOTH zero-result responses and positive results. The\n   * dominant case in production is the spelling source (match: .*)\n   * firing ~280ms LLM round-trips on neutral prose to find zero\n   * misspellings — caching that empty result is the biggest single win.\n   *\n   * Cache lifetime is tied to this group instance. When the resolver\n   * rebuilds sources (OPENCUES.md flags change, CUES.md edits, focus\n   * moves between cycling / non-cycling hosts), the group is\n   * reconstructed and this cache is GC'd with the old instance — no\n   * explicit invalidation needed.\n   *\n   * Cached values are SUB-CONTEXT-INDEXED (wordIndex 0..k matching the\n   * bucket order at dispatch time). On hit we remap to the CURRENT\n   * bucket's original indices, so the same sub-context text in a\n   * different surrounding buffer (same word set, different positions)\n   * is still correctly mapped.\n   *\n   * Bounded LRU; insertion order = recency since Map preserves\n   * insertion order and we delete+reinsert on hit. Mirrors the\n   * AgentRewrite._rewriteCache shape (see agent-rewrite.ts:209).\n   */\n  private readonly _resultCache = new Map<ConfigSource, Map<string, ReadonlyArray<CueResult>>>();\n  private static readonly CACHE_SIZE_PER_SOURCE = 64;\n\n  private readonly log?: (msg: string) => void;\n\n  private readonly decisions?: DecisionLegs;\n  private readonly wordGateThreshold: number;\n\n  constructor(config: RoutedWordSourceGroupConfig) {\n    this.id = config.id ?? 'word-cues';\n    this.log = config.log;\n    this.decisions = config.decisions;\n    this.wordGateThreshold = config.wordGateThreshold ?? WORD_GATE_THRESHOLD;\n    this.priority = config.sources.reduce((m, s) => Math.max(m, s.priority), 0);\n\n    const entries: RouteEntry[] = [];\n    for (const source of config.sources) {\n      const cfg = source.sourceConfig;\n      const entry: RouteEntry = { source, priority: source.priority };\n      if (cfg.match) {\n        try { entry.matchRe = new RegExp(cfg.match, 'i'); } catch { /* skip bad regex */ }\n      }\n      if (cfg.keywords) {\n        entry.keywords = cfg.keywords.split(',').map(k => k.trim().toLowerCase()).filter(Boolean);\n      }\n      // Reject sources with neither match nor keywords — every cue source\n      // must declare what it cares about. Catch-all \"default\" sources\n      // were removed; use an explicit `match: .*` or a keyword list.\n      if (!entry.matchRe && (!entry.keywords || entry.keywords.length === 0)) continue;\n      entries.push(entry);\n    }\n    this.entries = [...entries].sort((a, b) => b.priority - a.priority);\n  }\n\n  /** Word-cues apply when there's plain text to alt. Skip:\n   *   - empty inputs\n   *   - inputs containing a `_` blank — the user is invoking a lookup,\n   *     not asking for synonyms on surrounding words. Fluid-blank or\n   *     keyword-bound blank handlers own that resolve; word-cue LLM\n   *     calls just add latency without contributing to the answer. */\n  supports(context: CueContext): boolean {\n    if (!context.words || context.words.length === 0) return false;\n    if (context.words.some(w => w === '_')) return false;\n    return context.words.some(w => w.length > 0);\n  }\n\n  /**\n   * Route every highlighted word to one source, group, dispatch one\n   * LLM call per group in parallel, then map indices back.\n   */\n  async getCues(context: CueContext): Promise<CueSourceResult> {\n    const t0 = Date.now();\n\n    // Skip the \"in-progress\" trailing word — when the buffer ends in\n    // a non-whitespace character AND the cursor sits at end-of-buffer,\n    // the trailing word is almost certainly being typed (incomplete).\n    // Partial words can't be misspelled (the spelling LLM correctly\n    // skips them anyway) and don't usefully match cue sources yet\n    // (\"contr\" isn't a legal term until it becomes \"contract\").\n    // Skipping it from dispatch means:\n    //   - One fewer word in the spelling sub-context (shorter prompt)\n    //   - When the in-progress word is the ONLY cue-eligible word,\n    //     the entire LLM call is avoided.\n    // After the user types whitespace (space, newline, period+space),\n    // the now-complete word is no longer trailing and gets checked\n    // on the next resolve. Matches the timing of Word / Docs spell\n    // checkers — corrections appear after word completion, not mid-\n    // word. Conservative gate so we don't regress middle-of-text\n    // editing flows.\n    const inProgressIdx = findInProgressTrailingWord(context);\n\n    // DEHYDRATION (identity-context safe mode): PII words are dropped\n    // from LLM dispatch entirely — exactly like unrouted words (no cue,\n    // not navigable). Your name doesn't get sent out for synonyms.\n    // Over-dropping (a common surname word) only costs a cue;\n    // under-dropping ships a value to the provider.\n    const idCtx = context.identityContext;\n    const dehydrator = idCtx && idCtx.mode === 'safe' && idCtx.catalog.size > 0\n      ? getDehydrator(idCtx.catalog)\n      : undefined;\n\n    // Collect (word, originalIndex) for every cycleable word in the input.\n    const items = context.words\n      .map((word, idx) => ({ word, idx }))\n      .filter(({ word, idx }) => word !== '_' && word.length > 0 && idx !== inProgressIdx)\n      .filter(({ word }) => !dehydrator?.isPiiWord(word));\n\n    // Route each word. Words with no matching source are silently dropped\n    // (= no cue / not navigable). That's the user's choice when they don't\n    // configure a source that covers the word.\n    const groups = new Map<ConfigSource, { word: string; idx: number }[]>();\n    for (const item of items) {\n      const dest = this.classify(item.word);\n      if (!dest) continue;\n      let bucket = groups.get(dest);\n      if (!bucket) { bucket = []; groups.set(dest, bucket); }\n      bucket.push(item);\n    }\n\n    if (groups.size === 0) return { results: [], timing: Date.now() - t0 };\n\n    // One LLM call per source, parallel. Each call gets a sub-context\n    // containing only THAT source's words, renumbered 0..k. We remember\n    // the original indices to remap the response.\n    const dispatches = Array.from(groups.entries()).map(async ([source, fullBucket]) => {\n      // THE WORD GATE (decision layer): with a package that has the leg,\n      // one request per source asks which of its claimed words deserve an\n      // alternative under the cue. None → no chat call. Otherwise the call\n      // runs over the FULL bucket exactly as before (the cue reads phrases\n      // off the word sequence — `circle back` — so the input is never\n      // thinned) and the answers are kept only for the words the gate\n      // passed. The gate can spare a call or a false alternative, never\n      // lose a call: a failed request sends everything as before. Buckets\n      // over the cap go ungated (a `match: .*` cue on a long buffer).\n      const bucket = fullBucket;\n      let kept: Set<number> | null = null;\n      if (this.decisions?.wordGate && fullBucket.length > 0 && fullBucket.length <= WORD_GATE_MAX_WORDS && !context.signal?.aborted) {\n        try {\n          const cfg = source.sourceConfig;\n          const probs = await this.decisions.wordGate({ name: cfg.name, description: cfg.description, gate: cfg.gate }, context.text, fullBucket.map((b, i) => ({ id: `w${i + 1}`, word: b.word })), { signal: context.signal, log: (m: string) => this.log?.(m) });\n          kept = new Set(fullBucket.map((_, i) => i).filter((i) => (probs[i] ?? 1) >= this.wordGateThreshold));\n          this.log?.(`word-cues: gate kept ${kept.size}/${fullBucket.length} word(s) for '${source.id}'${kept.size === 0 ? ' — no call' : ''}`);\n          if (kept.size === 0) return [];\n        } catch (e) {\n          const err = e as Error;\n          if (err?.name === 'AbortError' || /abort/i.test(err?.message ?? '')) return [];\n          this.log?.(`word-cues: gate failed for '${source.id}' (${err?.message}) — every claimed word sent`);\n        }\n      }\n      const gateKeeps = (res: CueResult): boolean => kept === null || kept.has(res.wordIndex);\n      const subContextText = bucket.map((b, i) => `${i}=${b.word}`).join(' ');\n\n      // Cache lookup — keyed on the exact LLM input. Avoids the LLM\n      // round-trip when this child source has already answered for the\n      // same word set (regardless of where those words sit in the\n      // surrounding buffer).\n      const sourceCache = this._cacheFor(source);\n      const cached = sourceCache.get(subContextText);\n      if (cached !== undefined) {\n        // Reinsert for LRU recency.\n        sourceCache.delete(subContextText);\n        sourceCache.set(subContextText, cached);\n        return cached.filter(gateKeeps).map<CueResult>(res => ({\n          ...res,\n          wordIndex: bucket[res.wordIndex]?.idx ?? res.wordIndex,\n        }));\n      }\n\n      const subContext: CueContext = {\n        ...context,\n        words: bucket.map(b => b.word),\n        text: subContextText,\n      };\n      const result = await source.getCues(subContext);\n\n      // NEVER cache an error envelope. A transient dispatch failure\n      // (abort, 429, provider schema-validation flake) carries\n      // `results: []`; caching it would answer \"no cues\" for this\n      // exact word set until the next source rebuild — a permanent,\n      // SILENT poison, because the resolver ignores per-source\n      // `error` fields. Found live 2026-07-20: groq/gpt-oss\n      // intermittently fails its own JSON-schema enforcement on the\n      // spelling prompt (~1/3 of dispatches), and the cached empty\n      // read as \"word-cues never fire\" for the whole session. The\n      // log line below is the only failure signal — keep it.\n      if (result.error) {\n        this.log?.(`word-cues: source '${source.id}' dispatch failed (not cached): ${result.error}`);\n        return result.results.filter(gateKeeps).map<CueResult>(res => ({\n          ...res,\n          wordIndex: bucket[res.wordIndex]?.idx ?? res.wordIndex,\n        }));\n      }\n\n      // Cache the SUB-CONTEXT-INDEXED results so the remap on hit\n      // works against any future bucket order. Caches empty arrays\n      // too — that's the dominant win for spelling on neutral prose.\n      sourceCache.set(subContextText, result.results);\n      while (sourceCache.size > RoutedWordSourceGroup.CACHE_SIZE_PER_SOURCE) {\n        const oldest = sourceCache.keys().next().value;\n        if (oldest === undefined) break;\n        sourceCache.delete(oldest);\n      }\n\n      // Map sub-context indices back to original context indices.\n      return result.results.filter(gateKeeps).map<CueResult>(res => ({\n        ...res,\n        wordIndex: bucket[res.wordIndex]?.idx ?? res.wordIndex,\n      }));\n    });\n\n    const settled = await Promise.all(dispatches);\n    return {\n      results: settled.flat(),\n      timing: Date.now() - t0,\n    };\n  }\n\n  /**\n   * Pick the destination source for one word. Public for testability.\n   * Highest-priority source whose match/keywords cover the word wins;\n   * null if no source claims it.\n   */\n  classify(word: string): ConfigSource | null {\n    const lower = word.toLowerCase();\n    for (const entry of this.entries) {\n      if (entry.matchRe && entry.matchRe.test(word)) return entry.source;\n      if (entry.keywords && entry.keywords.includes(lower)) return entry.source;\n    }\n    return null;\n  }\n\n  /** Public for tests / debug — count of routed sources. */\n  get routingStats(): { sources: number } {\n    return { sources: this.entries.length };\n  }\n\n  /** Public for tests / debug — cache size per child source.\n   *  Returns 0 entries for any source that hasn't been dispatched yet. */\n  cacheSizes(): Map<ConfigSource, number> {\n    const out = new Map<ConfigSource, number>();\n    for (const [source, cache] of this._resultCache) out.set(source, cache.size);\n    return out;\n  }\n\n  private _cacheFor(source: ConfigSource): Map<string, ReadonlyArray<CueResult>> {\n    let cache = this._resultCache.get(source);\n    if (!cache) {\n      cache = new Map();\n      this._resultCache.set(source, cache);\n    }\n    return cache;\n  }\n}\n"
